#review-view .booking-optional{font-size:14px;font-weight:500;line-height:1.5;color:var(--muted);}
#review-view #request-name{font-size:16px;font-weight:500;line-height:1.5;font-family:inherit;width:100%;min-width:0;padding:12px;border:0;background:transparent;color:var(--text);min-height:48px;}
#review-view #request-note{font-size:16px;font-weight:500;line-height:1.5;font-family:inherit;width:100%;min-width:0;padding:12px;border:0;background:transparent;color:var(--text);min-height:88px;resize:vertical;}

