#review-view .booking-total dt{font-size:18px;font-weight:700;line-height:1.5}
#review-view .booking-total dd{font-size:18px;font-weight:700;line-height:1.5}
#review-view .booking-policy{display:grid;gap:4px;margin-top:16px}
#review-view .booking-policy p{font-size:14px;font-weight:500;line-height:1.5;color:var(--muted);margin:0}

#review-view .booking-submit{display:flex;flex-direction:column;gap:12px;padding:16px 20px 24px;background-color:var(--surface);}
#review-view #request-form-error{font-size:16px;font-weight:500;line-height:1.5;color:var(--error);margin:0;word-break:keep-all;overflow-wrap:anywhere;}
#review-view #request-form-reload{font-size:16px;font-weight:600;line-height:1.5;min-height:44px;padding:12px;border:0;border-radius:8px;}
#review-view #save-request{width:100%;min-height:48px;padding:16px;border:0;border-radius:8px;background-color:var(--action);color:white;font-size:16px;font-weight:600;line-height:1.5;word-break:keep-all;overflow-wrap:anywhere;}
#review-view #save-request:disabled{opacity:.6;}

#review-view .booking-identity{container-type:inline-size;container-name:booking-trip;}
#review-view .booking-pricing{container-type:inline-size;container-name:booking-price;}
#review-view .booking-meta,#review-view .booking-date-label,#review-view .booking-pricing dt,#review-view .booking-pricing dd{word-break:keep-all;overflow-wrap:anywhere;}
@container booking-trip (max-width:20em){#review-view .booking-date{padding:4px}#review-view .booking-nights{padding-inline:0}}
#review-view .booking-dates[data-trip-stacked="true"]{grid-template-columns:minmax(0,1fr)}
@container booking-price (max-width:15em){#review-view .booking-pricing dl>div{grid-template-columns:minmax(0,1fr);}}

#review-view .booking-date{align-items:flex-start}
#review-view .booking-date-label{text-align:start}
#review-view .booking-date strong{text-align:start}

#review-view .booking-dates{background-color:var(--quiet)}
#review-view .booking-date{background-color:transparent;border-radius:0px}

#review-view .booking-header{padding-inline:0}

#review-view .booking-guest{padding-block:24px;display:flex;flex-direction:column;gap:16px;margin:0;}
#review-view #edit-request-guest{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;min-height:44px;padding:0;border:0;background:transparent;text-align:start;font:inherit;}
#review-view #request-guest-summary{font-size:16px;font-weight:500;line-height:1.5;color:var(--muted);min-width:0;word-break:keep-all;overflow-wrap:anywhere;}
#review-view #edit-request-guest img{width:20px;height:20px;flex-shrink:0;}
#guest-dialog .booking-field{display:flex;flex-direction:column;gap:8px;margin-bottom:16px;}
#guest-dialog label{font-size:16px;font-weight:600;line-height:1.5;}
#guest-dialog .booking-optional{font-size:14px;font-weight:500;line-height:1.5;color:var(--muted);}
#guest-dialog input,#guest-dialog textarea{font:inherit;font-size:16px;font-weight:500;line-height:1.5;width:100%;min-width:0;padding:12px;border:0;background:transparent;color:var(--text);}
#guest-dialog textarea{min-height:88px;resize:vertical;}
#guest-dialog textarea:focus{outline:none;}
#guest-dialog .sheet-heading h2{flex:1;min-width:0;word-break:keep-all;overflow-wrap:anywhere;}
#guest-dialog .sheet-heading button{flex-shrink:0;word-break:keep-all;min-width:44px;}
#guest-form-error{font-size:16px;font-weight:500;line-height:1.5;color:var(--error);min-width:0;word-break:keep-all;overflow-wrap:anywhere;}


#main-content:has(#requests-view:not([hidden])),#main-content:has(#request-detail-view:not([hidden])){padding-inline:0}
#main-content:has(#request-detail-view:not([hidden])){padding-bottom:0}
#requests-view{display:flex; flex-direction:column; min-width:0; min-height:calc(100dvh - var(--nav-height) - 24px); background-color:var(--surface)}
#requests-view h1{font-family: "Noto Sans KR",sans-serif; font-size:16px; font-weight:600; line-height:1.5; text-align:center; padding:12px var(--page-inset); margin:0}
#requests-empty{flex:1; display:flex; flex-direction:column; justify-content:center; align-items:center; gap:16px; padding:32px var(--page-inset); min-width:0}
#requests-empty h2{font-family: "Noto Sans KR",sans-serif; font-size:18px; font-weight:600; line-height:1.5; text-align:center; word-break:keep-all; overflow-wrap:anywhere}
#requests-empty a{display:inline-flex; justify-content:center; align-items:center; min-height:48px; padding:12px 16px; border:0; border-radius:8px; background-color:var(--action); color:var(--surface); font-family: "Noto Sans KR",sans-serif; font-size:16px; font-weight:600; line-height:1.5; text-decoration:none; max-width:100%; word-break:keep-all; overflow-wrap:anywhere}
#request-list{display:grid; grid-template-columns:1fr; gap:8px; min-width:0; background-color:var(--quiet)}
.request-card{display:grid; gap:8px; padding:16px var(--page-inset); background-color:var(--surface); min-width:0}
.request-card a{display:flex; flex-direction:row; align-items:center; gap:8px; min-height:44px; min-width:0; text-decoration:none}
.request-card h2{font-family: "Noto Sans KR",sans-serif; font-size:18px; font-weight:600; line-height:1.5; flex:1; min-width:0; margin:0; word-break:keep-all; overflow-wrap:anywhere}
.request-card a img{width:20px; height:20px; flex-shrink:0}
[data-request-status],[data-request-room]{font-family: "Noto Sans KR",sans-serif; font-size:14px; font-weight:500; line-height:1.5; color:var(--muted); margin:0; min-width:0; word-break:keep-all; overflow-wrap:anywhere}
[data-request-trip],#request-detail-trip{display:flex; flex-direction:row; flex-wrap:wrap; align-items:baseline; column-gap:8px; row-gap:4px; font-family: "Noto Sans KR",sans-serif; font-size:14px; font-weight:500; line-height:1.5; color:var(--muted); min-width:0}
.request-trip-date{display:inline-block; max-width:100%; white-space:nowrap}
.request-trip-meta{flex-basis:100%; white-space:normal; min-width:0; word-break:keep-all; overflow-wrap:anywhere}
[data-request-total]{font-family: "Noto Sans KR",sans-serif; font-size:18px; font-weight:700; line-height:1.5; display:block; color:var(--action); text-align:end; min-width:0; overflow-wrap:anywhere}
#requests-error,#request-detail-error{font-family: "Noto Sans KR",sans-serif; font-size:16px; font-weight:500; line-height:1.5; color:var(--error); padding-inline:var(--page-inset); min-width:0; word-break:keep-all; overflow-wrap:anywhere}
.request-outcome{font-family: "Noto Sans KR",sans-serif; font-size:22px; font-weight:700; line-height:1.5; background-color:var(--surface); padding:16px var(--page-inset); min-width:0; word-break:keep-all; overflow-wrap:anywhere}
#requests-reload,#request-detail-reload{font-family: "Noto Sans KR",sans-serif; font-size:16px; font-weight:600; line-height:1.5; min-height:44px; padding:12px 16px; margin:16px var(--page-inset); border:0; border-radius:8px; background-color:var(--quiet); color:var(--text); word-break:keep-all; overflow-wrap:anywhere}

#request-detail-view{display:flex; flex-direction:column; gap:8px; background-color:var(--quiet); min-width:0;}
.request-detail-header{display:grid; grid-template-columns:44px minmax(0,1fr) 44px; align-items:center; gap:0; padding:8px var(--page-inset); background-color:var(--surface);}
.request-detail-header h1{font-size:16px; font-weight:600; line-height:1.5; text-align:center; margin:0; min-width:0; word-break:keep-all; overflow-wrap:anywhere;}
.request-detail-header>span{width:44px;}
#request-detail-content{display:grid; gap:8px; min-width:0; background-color:var(--quiet);}
.request-detail-group{background-color:var(--surface); padding:24px var(--page-inset); display:flex; flex-direction:column; gap:8px; min-width:0;}
#request-detail-stay{font-size:18px; font-weight:600; line-height:1.5; margin:0; min-width:0; word-break:keep-all; overflow-wrap:anywhere;}
.request-detail-group h2:not(#request-detail-stay){font-size:16px; font-weight:600; line-height:1.5; margin:0; word-break:keep-all; overflow-wrap:anywhere;}
#request-detail-status,#request-detail-room{font-size:14px; font-weight:500; line-height:1.5; color:var(--muted); margin:0; min-width:0; word-break:keep-all; overflow-wrap:anywhere;}
.request-detail-group dl{display:grid; gap:16px; margin:0; padding:0; min-width:0;}
.request-detail-group dl>div{display:grid; gap:4px; min-width:0;}
.request-detail-group dt{font-size:14px; font-weight:500; line-height:1.5; color:var(--muted); margin:0; word-break:keep-all; overflow-wrap:anywhere;}
.request-detail-group dd{font-size:16px; font-weight:500; line-height:1.5; margin:0; min-width:0; word-break:keep-all; overflow-wrap:anywhere;}

.request-detail-price dl{display: grid; gap: var(--control-gap); margin: 0; padding: 0;}
.request-detail-price dl>div{display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: var(--label-gap); min-width: 0;}
.request-detail-price dt{font-size: 16px; font-weight: 500; line-height: 1.5; color: var(--text); margin: 0; min-width: 0; word-break: keep-all; overflow-wrap: anywhere;}
.request-detail-price dd{font-size: 16px; font-weight: 500; line-height: 1.5; margin: 0; margin-inline-start: auto; max-width: 100%; min-width: 0; text-align: end; word-break: keep-all; overflow-wrap: anywhere;}
.request-detail-total{margin-top: 24px;}
#request-detail-total{font-size: 18px; font-weight: 700; line-height: 1.5; color: var(--action);}
.request-detail-policy{display: grid; gap: 4px; margin-top: 16px;}
.request-detail-policy p{font-size: 14px; font-weight: 500; line-height: 1.5; color: var(--muted); margin: 0; word-break: keep-all; overflow-wrap: anywhere;}
.request-detail-actions{background-color: var(--surface); padding: 16px var(--page-inset) 24px;}
#cancel-request{width: 100%; min-height: 48px; padding: 12px; border: 0; border-radius: 8px; font-size: 16px; font-weight: 600; line-height: 1.5; word-break: keep-all; overflow-wrap: anywhere;}
#review-view .booking-total dd{color: var(--action);}

#cancel-request-title{font-size: 22px; font-weight: 700; line-height: 1.5; color: var(--text); margin: 0; min-width: 0; word-break: keep-all; overflow-wrap: anywhere;}
#cancel-request-subject{font-size: 16px; font-weight: 500; line-height: 1.5; color: var(--text); margin-top: 16px; word-break: keep-all; overflow-wrap: anywhere;}
#cancel-request-dialog>p:not([id]){font-size: 14px; font-weight: 500; line-height: 1.5; color: var(--muted); margin-top: 8px; word-break: keep-all; overflow-wrap: anywhere;}
#cancel-request-error{font-size: 16px; font-weight: 500; line-height: 1.5; color: var(--error); margin-top: 16px; word-break: keep-all; overflow-wrap: anywhere;}
#cancel-request-reload{font-size: 16px; font-weight: 600; line-height: 1.5; min-height: 44px; padding: 12px 16px; border: 0; border-radius: 8px; background: var(--quiet); color: var(--text); margin-top: 12px; word-break: keep-all; overflow-wrap: anywhere;}
.request-cancel-actions{display: flex; flex-direction: row; flex-wrap: wrap; gap: 8px; margin-top: 24px;}
#keep-request,#confirm-cancel-request{font-size: 16px; font-weight: 600; line-height: 1.5; min-height: 48px; padding: 12px; border: 0; border-radius: 8px; flex: 1 1 calc(4em + 24px); max-width: 100%; word-break: keep-all; overflow-wrap: anywhere;}
#keep-request{background: var(--quiet); color: var(--text);}
#confirm-cancel-request{background: var(--error); color: var(--surface);}

#cancel-request-subject{display:flex;flex-direction:row;flex-wrap:wrap;column-gap:8px;row-gap:4px}
.request-cancel-name{flex-basis:100%;min-width:0;max-width:100%}

